import re, subprocess, random, sys
random.seed(7)

SRC='input.tex.bak'
fam={}
for line in open('synonyms.txt'):
    line=line.strip()
    if not line: continue
    parts=[p.strip() for p in line.split(',') if p.strip()]
    if parts: fam[parts[0]]=list(dict.fromkeys(parts))

main=open('main.tex').read()
preamble=main.split(r'\begin{document}')[0]
lines=open(SRC).read().split('\n')

def parse_log(log,n):
    parts=re.split(r'<<<VAR(\d+)>>>',log)
    res={}
    for i in range(1,len(parts),2):
        idx=int(parts[i]); body=parts[i+1]
        res[idx]=[float(x) for x in re.findall(r'Overfull \\hbox \(([\d.]+)pt too wide\)',body)]
    out=[]
    for i in range(n):
        a=res.get(i)
        out.append(None if a is None else (len(a),round(sum(a),4)))
    return out

def eval_batch(texts):
    body=''
    for i,v in enumerate(texts):
        body+='\n\\typeout{<<<VAR%d>>>}\n'%i + v + '\n\n'
    doc=preamble+'\\begin{document}\n'+body+'\\end{document}\n'
    open('batch.tex','w').write(doc)
    subprocess.run(['pdflatex','-interaction=nonstopmode','-jobname=batch','batch.tex'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
    try:
        log=open('batch.log',errors='ignore').read()
    except IOError:
        return [None]*len(texts)
    return parse_log(log,len(texts))

def search(toks,sl,maxgen=40):
    opts=[list(dict.fromkeys(fam[t])) for (i,t) in sl]
    n=len(sl)
    cache={}
    def render(state):
        out=list(toks)
        for k,(i,t) in enumerate(sl): out[i]=state[k]
        return ''.join(out)
    def evaluate(states):
        uniq=list(dict.fromkeys(states))
        need=[s for s in uniq if s not in cache]
        for start in range(0,len(need),60):
            chunk=need[start:start+60]
            res=eval_batch([render(s) for s in chunk])
            if len(res)!=len(chunk) or any(r is None for r in res):
                for s in chunk:
                    r=eval_batch([render(s)])
                    cache[s]=r[0] if (len(r)==1 and r[0] is not None) else (999,1e6)
            else:
                for s,r in zip(chunk,res): cache[s]=r
        return [cache[s] for s in states]
    base=tuple(t for (i,t) in sl)
    bc=evaluate([base])[0]
    if bc[0]==0:
        return base,bc,cache,render
    beam=[base]
    best=base; bestc=bc; stall=0
    for gen in range(1,maxgen+1):
        cands=[]
        for s in beam:
            for k in range(n):
                for o in opts[k]:
                    if o!=s[k]:
                        ns=list(s); ns[k]=o; cands.append(tuple(ns))
        if stall>=3:
            for _ in range(200):
                ns=list(best)
                for _ in range(random.randint(1,4)):
                    k=random.randrange(n); ns[k]=random.choice(opts[k])
                cands.append(tuple(ns))
            stall=0
        cands=list(dict.fromkeys(cands))
        if not cands: break
        costs=evaluate(cands)
        paired=sorted(zip(cands,costs),key=lambda x:(x[1][0],x[1][1]))
        beam=[s for s,c in paired[:8]]
        if paired[0][1] < bestc:
            best=paired[0][0]; bestc=paired[0][1]
        else:
            stall+=1
        print('gen',gen,'best',bestc,'cache',len(cache),flush=True)
        if bestc[0]==0: break
    return best,bestc,cache,render

out=list(lines)
total_before=0
total_after=0
for idx,text in enumerate(lines):
    if not text.strip(): continue
    toks=re.findall(r'\w+|\W+',text)
    sl=[(i,t) for i,t in enumerate(toks) if t in fam]
    if not sl:
        continue
    b,c,cache,render=search(toks,sl)
    newtext=render(b)
    print('LINE',idx+1,'slots',len(sl),'cost before?',None,'best',c,flush=True)
    out[idx]=newtext
    print('  changed:',[(sl[k][1],b[k]) for k in range(len(sl)) if b[k]!=sl[k][1]],flush=True)

open('input.new.tex','w').write('\n'.join(out))
print('written input.new.tex')
PYEOF
